const draftFunctionSource = source.match(/function providerModelSyncDraftFingerprint\(w\)\{[^\n]+\}\nfunction providerModelSyncHasDraft\(w\)\{[^\n]+\}/)?.[0];
assert.ok(draftFunctionSource, 'model synchronization draft helpers must remain executable');
const draftTools = new Function('providerModelSyncDraftValue', `${draftFunctionSource};return {fingerprint:providerModelSyncDraftFingerprint,hasDraft:providerModelSyncHasDraft}`)(
  wizard => ({ name:wizard.name.trim(), modelSyncInterval:wizard.modelSyncInterval }),
);
const syncDraft = { name:'Provider A', modelSyncInterval:'1h' };
syncDraft.modelSyncDraftBaseline = draftTools.fingerprint(syncDraft);
assert.equal(draftTools.hasDraft(syncDraft), false, 'an unchanged Provider may synchronize immediately');
syncDraft.name = 'Provider A draft';
assert.equal(draftTools.hasDraft(syncDraft), true, 'an unsaved Provider name must block immediate synchronization');
syncDraft.name = 'Provider A';
syncDraft.modelSyncInterval = '30m';
assert.equal(draftTools.hasDraft(syncDraft), true, 'an unsaved synchronization interval must block immediate synchronization');

