const catalogTools=new Function(`${source.slice(catalogHelpersStart,catalogHelpersEnd)};return {uses:providerUsesControlPlaneCatalog,catalog:providerModelSyncCatalogPayload,credential:providerModelSyncCatalogCredentialPayload,validate:validateProviderModelSyncCatalog}`)();
const catalogDraft={type:'custom',modelSyncCatalogMode:'volcengine-plan',modelSyncCatalog:{type:'volcengine-plan',plan:'coding',credentialRef:'store:ark-control'},modelSyncCatalogReplace:false,modelSyncCatalogCredential:{accessKeyId:'',secretAccessKey:'',sessionToken:''}};
assert.deepEqual(catalogTools.catalog(catalogDraft),{type:'volcengine-plan',plan:'coding',credentialRef:'store:ark-control'});
assert.equal(catalogTools.credential(catalogDraft),null,'saved Plan credentials must be retained by reference without being read back');
assert.equal(catalogTools.validate(catalogDraft),'');
catalogDraft.modelSyncCatalogReplace=true;
assert.match(catalogTools.validate(catalogDraft),/Access Key ID is required/,'credential replacement must require a complete AK/SK pair');
catalogDraft.modelSyncCatalogCredential={accessKeyId:'AK_TEST',secretAccessKey:'SK_TEST',sessionToken:'STS_TEST'};
assert.deepEqual(catalogTools.credential(catalogDraft),{access_key_id:'AK_TEST',secret_access_key:'SK_TEST',session_token:'STS_TEST'});
assert.equal(catalogTools.validate(catalogDraft),'');
catalogDraft.type='cliproxy-codex';
assert.equal(catalogTools.catalog(catalogDraft),null,'Codex Providers must not accept the Volcengine control-plane catalog UI state');

const mergeStart = source.indexOf('function mergeProviderModelSyncDraft(');
const mergeEnd = source.indexOf('\nfunction updateProviderModelSyncDraftUI', mergeStart);
assert.ok(mergeStart >= 0 && mergeEnd > mergeStart, 'model synchronization draft merge helper must remain executable');
const mergeProviderModelSyncDraft = new Function(`${source.slice(mergeStart, mergeEnd)};return mergeProviderModelSyncDraft`)();
const inFlightDraft = {
  type:'custom', name:'Provider A typed while syncing', modelSyncInterval:'30m', catalog:['stable'], modelSync:{ status:'running' },
  protocols:[{ protocol:'openai-chat', models:['stable','manual-draft'], manualModels:['manual-draft'], modelSpecs:{} }],
  modelSyncDraftBaseline:'previous-server-state',
};
const freshProvider = {
  type:'custom', name:'Provider A saved', modelSyncInterval:'1h', catalog:['stable','new-upstream'], modelSync:{ status:'succeeded', added_models:1 },
  protocols:[{ protocol:'openai-chat', models:['stable','new-upstream'], manualModels:[], modelSpecs:{ 'new-upstream':{ upstream_model:'new-upstream' } } }],
  modelSyncDraftBaseline:'latest-server-state',
};
mergeProviderModelSyncDraft(inFlightDraft, freshProvider, new Set(['new-upstream']));
assert.equal(inFlightDraft.name, 'Provider A typed while syncing', 'in-flight Provider name edits must survive a synchronization refresh');
assert.equal(inFlightDraft.modelSyncInterval, '30m', 'in-flight schedule edits must survive a synchronization refresh');
assert.deepEqual(inFlightDraft.protocols[0].models, ['stable','manual-draft','new-upstream'], 'the synchronization result must add new models without discarding draft models');
assert.equal(inFlightDraft.modelSync.status, 'succeeded', 'persisted synchronization status must still refresh around an in-flight draft');
assert.equal(inFlightDraft.modelSyncDraftBaseline, 'latest-server-state', 'dirty detection must compare the preserved draft with the latest persisted Provider');

