// A committed route must be acknowledged while audit history is still loading.
// History failures must not turn a successful write into an apparent failure.
{
  const start=source.indexOf("  if(action==='routing-apply'){");
  const end=source.indexOf("  if(action==='add-provider')",start);
  assert.ok(start>=0&&end>start);
  const buildAction=new Function('state','adapter','closeOverlay','showToast','loadAndRenderModel',
    `return async function(){const action='routing-apply',el={dataset:{model:'smart'}};${source.slice(start,end)}}`);
  const events=[];
  let rejectHistory;
  const history=new Promise((resolve,reject)=>{rejectHistory=reject});
  const routingState={routingReview:{draftId:'review'},modelCache:new Map([['smart',{}]]),revisions:[]};
  const run=buildAction(routingState,{
    applyRouting:async()=>({revision:42}),getRevisions:()=>history,
  },()=>events.push('closed'),(message,type)=>events.push(type||'success'),async()=>events.push('model refreshed'));
  const saving=run();
  await Promise.resolve();
  assert.deepEqual(events,['closed','success','model refreshed'],'saving must not wait for history to acknowledge the committed route or refresh the model');
  assert.equal(routingState.modelCache.has('smart'),false);
  rejectHistory(new Error('history unavailable'));
  await saving;
  assert.ok(!events.includes('error'),'a history failure must not misreport the committed route as failed');
  events.length=0;
  const failed=buildAction(routingState,{applyRouting:async()=>{throw new Error('apply failed')}},
    ()=>events.push('closed'),(message,type)=>events.push(type||'success'),async()=>events.push('model refreshed'));
  await failed();
  assert.deepEqual(events,['error'],'a rejected apply must keep the review open and report failure');
}
console.log('PASS route-save acknowledgement is independent of revision history latency and failure');
